package com.punjabibeats.app.data.resolver

/**
 * ~1 second of true-silence WAV (8kHz, 8-bit, mono), base64-encoded. Used as an
 * inline `data:` URI when every resolver in the chain fails for a track: the
 * placeholder keeps queue indices stable and plays through in a blink instead
 * of throwing the player into an error state.
 */
object SilenceAsset {
    const val SILENT_WAV_BASE64 = ""

    const val DATA_URI_PREFIX = "data:audio/wav;base64,"
}
